import { tags } from "typia";

/**
 * Aggregated review analytics for a product, providing summary statistics of customer ratings and review activity trends including total review count, average rating score, distribution across 5-star ratings, and recent review submissions from the past week.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IEcommerceMallDashboardReviewAnalytic = {
  /**
   * Total number of active reviews for this product.
   *
   * @x-autobe-specification COUNT(*) from ecommerce_mall_reviews where product=TARGET_PRODUCT AND is_active=true
   */
  totalReviews: number & tags.Type<"int32">;

  /**
   * Average star rating calculated from all active customer reviews.
   *
   * @x-autobe-specification ROUND(AVG(rating), 2) from ecommerce_mall_reviews where product=TARGET_PRODUCT AND is_active=true
   */
  averageRating: number;

  /**
   * Breakdown of review counts by star rating (1-5 stars) for this product.
   *
   * @x-autobe-specification GROUP BY rating (1-5) from ecommerce_mall_reviews where product=TARGET_PRODUCT AND is_active=true, returning count for each rating level
   */
  reviewDistribution: {
    rating1: number & tags.Type<"int32">;
    rating2: number & tags.Type<"int32">;
    rating3: number & tags.Type<"int32">;
    rating4: number & tags.Type<"int32">;
    rating5: number & tags.Type<"int32">;
  };

  /**
   * Number of reviews submitted within the past seven days for this product.
   *
   * @x-autobe-specification COUNT(*) from ecommerce_mall_reviews where product=TARGET_PRODUCT AND is_active=true AND created_at >= NOW() - INTERVAL '7 days'
   */
  newlySubmittedThisWeek: number & tags.Type<"int32">;
};
